#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-08-31
//
// write-operator-permissions.mjs (#3835): deliver ork's canonical deny rules to
// a settings scope Claude Code actually reads. A plugin settings.json is inert
// (CC picks only `agent`/`subagentStatusLine`), so the rules must live in the
// OPERATOR's own file. This script is the consent boundary: the setup/doctor
// skills print what it WOULD do (--dry-run) and run it only after the user says
// yes in chat.
//
//   node write-operator-permissions.mjs --scope user|project [--dry-run] [--json]
//   node write-operator-permissions.mjs --scope user --rollback
//
// Behaviour: set-union into permissions.deny (never removes, never reorders the
// user's own rules), full-file backup at <target>.ork-backup-<stamp> before any
// write, --rollback restores the newest backup. Unparseable target: exit 2 and
// touch nothing. The sandboxSuggestion block is PRINTED, never written: the
// network allowlist is machine-specific and belongs to the operator.
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, copyFileSync } from 'node:fs';
import { dirname, join, resolve, basename } from 'node:path';
import { homedir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const PAYLOAD_PATH = resolve(HERE, '..', 'references', 'operator-permissions.json');

function fail(msg, code = 2) {
  console.error(`ERROR: ${msg}`);
  process.exit(code);
}

const args = process.argv.slice(2);
const has = (f) => args.includes(f);
const scopeIx = args.indexOf('--scope');
const scope = scopeIx >= 0 ? args[scopeIx + 1] : null;
const pathIx = args.indexOf('--settings-path');
const overridePath = pathIx >= 0 ? args[pathIx + 1] : null;
if (has('--help') || (!scope && !overridePath)) {
  console.log('usage: write-operator-permissions.mjs --scope user|project [--dry-run] [--rollback] [--json] [--settings-path <file>]');
  process.exit(args.length === 0 || has('--help') ? 0 : 2);
}
if (scope && !['user', 'project'].includes(scope)) fail(`--scope must be user or project, got '${scope}'`);

const target = overridePath
  ? resolve(overridePath)
  : scope === 'user'
    ? join(process.env.ORK_SETTINGS_HOME || homedir(), '.claude', 'settings.json')
    : join(process.cwd(), '.claude', 'settings.json');

if (has('--rollback')) {
  const dir = dirname(target);
  const base = `${basename(target)}.ork-backup-`;
  const backups = existsSync(dir) ? readdirSync(dir).filter((n) => n.startsWith(base)).sort() : [];
  if (backups.length === 0) fail(`no ${base}* found next to ${target}`, 3);
  const latest = join(dir, backups[backups.length - 1]);
  copyFileSync(latest, target);
  console.log(`restored ${target} from ${latest}`);
  process.exit(0);
}

const payload = JSON.parse(readFileSync(PAYLOAD_PATH, 'utf8'));
let current = {};
if (existsSync(target)) {
  const raw = readFileSync(target, 'utf8');
  try {
    current = JSON.parse(raw);
  } catch {
    fail(`${target} is not valid JSON; fix it by hand first (nothing was touched)`);
  }
}
const perms = current.permissions && typeof current.permissions === 'object' ? current.permissions : {};
const existing = Array.isArray(perms.deny) ? perms.deny : [];
const additions = payload.deny.filter((r) => !existing.includes(r));
const result = {
  target,
  already_present: payload.deny.length - additions.length,
  additions,
  sandbox_suggestion: payload.sandboxSuggestion,
  applied: false,
};

function renderText(r) {
  const lines = [
    `target: ${r.target}`,
    `already present: ${r.already_present}  additions: ${r.additions.length}`,
    ...r.additions.map((a) => `  + ${a}`),
    r.applied ? `written; backup: ${r.backup || '(no prior file)'}` : `NOT written (${r.note})`,
    r.applied && r.rollback ? `rollback: ${r.rollback}` : '',
    'sandbox suggestion (print-only; adjust domains, then paste into the same file):',
    JSON.stringify(r.sandbox_suggestion, null, 2),
  ];
  return lines.filter(Boolean).join('\n');
}

if (has('--dry-run') || additions.length === 0) {
  result.note = additions.length === 0 ? 'every payload rule is already present; nothing to write' : 'dry run; nothing written';
  console.log(has('--json') ? JSON.stringify(result, null, 2) : renderText(result));
  process.exit(0);
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backup = `${target}.ork-backup-${stamp}`;
mkdirSync(dirname(target), { recursive: true });
if (existsSync(target)) copyFileSync(target, backup);
current.permissions = { ...perms, deny: [...existing, ...additions] };
writeFileSync(target, JSON.stringify(current, null, 2) + '\n');
// read back: a write that cannot be re-parsed is not a delivery
JSON.parse(readFileSync(target, 'utf8'));
result.applied = true;
result.backup = existsSync(backup) ? backup : null;
result.rollback = result.backup
  ? `node ${process.argv[1]} ${overridePath ? `--settings-path ${target}` : `--scope ${scope}`} --rollback`
  : 'delete the added permissions.deny entries (target had no prior file)';
console.log(has('--json') ? JSON.stringify(result, null, 2) : renderText(result));
